  Lemma new_block_outside : forall s' NEW LB m' p A n SP a,
    as_RHEAP H s' (NEW ++ LB) m' -> In (p, A, n) NEW -> aceil <= SP -> aclient_addr H LB SP a -> a + 1 <= A \/ A + n <= a.
  Proof.
    intros s' NEW LB m' p A n SP a HP Hb CE HC.
    eapply new_block_disjoint_client; [exact HP| exact Hb| apply aclient_addr_range; exact HC| exact CE| lia].
  Qed.

  (* [comment removed for export] *)
  Lemma new_block_outside_aobj : forall s LB m LF m1 s' NEW m' p A n a k,
    as_RHEAP H s LB m -> as_RFS H LF m1 -> as_RHEAP H s' (NEW ++ LB) m' -> In (p, A, n) NEW -> aobj LB LF a k -> 0 < k ->
    a + k <= A \/ A + n <= a.
  Proof.
    intros s LB m LF m1 s' NEW m' p A n a k RH RF RH' Hb AO Hk.
    eapply new_block_disjoint_client with (SP := aceil); [exact RH'| exact Hb| eapply (aobj_client H HH); [exact RH| exact RF| exact AO] | lia| exact Hk].
  Qed.

  (* [comment removed for export] *)
  Lemma xpres_drop_new : forall s' NEW LB m0 SP X Y m m',
    as_RHEAP H s' (NEW ++ LB) m0 -> aceil <= SP ->
    Forall (fun iv : Z * Z => exists p A n, In (p, A, n) NEW /\ A <= fst iv /\ snd iv <= A + n) Y ->
    xpres H LB SP (X ++ Y) m m' -> xpres H LB SP X m m'.
  Proof.
    intros s' NEW LB m0 SP X Y m m' HP CE FY XP a Ha [HC NX]. apply XP; [exact Ha|]. split; [exact HC|].
    intros K. apply rin_ivs_app in K. destruct K as [K|K]; [exact (NX K)|].
    clear - HH HP CE FY HC K. induction Y as [|[l h] Y IH]; [destruct K|].
    pose proof (Forall_inv FY) as (p & A & n & Hb & B1 & B2). cbn in B1, B2. cbn in K.
    destruct K as [K|K]; [| exact (IH (Forall_inv_tail FY) K)].
    pose proof (new_block_outside _ _ _ _ _ _ _ _ _ HP Hb CE HC). lia.
  Qed.

