  Lemma xpres_free : forall s LB m p Ap np SP SP' X m3 m4,
    as_RHEAP H s LB m -> In (p, Ap, np) LB ->
    apres H (as_lb_remove H p LB) SP' m3 m4 -> SP' <= SP ->
    (forall a, Ap <= a < Ap + np -> rin_ivs X a) ->
    (forall a, sh Ap <= a < sh Ap + nsh np -> rin_ivs X a) ->
    xpres H LB SP X m3 m4.
  Proof.
    intros s LB m p Ap np SP SP' X m3 m4 HP Hin PRES HS HX HXS a Ha [HC NX].
    apply PRES; [exact Ha|].
    unfold aclient_addr in *.
    destruct HC as [K|[K|[(b & Hb & K)|[(b & Hb & K)|K]]]]; [left; lia| right; left; exact K| | | right; right; right; right; exact K].
    - right; right; left. exists b. split; [| exact K].
      apply (ah_lb_remove_keep H HH); [exact (ah_nodup H HH _ _ _ HP)| exact Hb|].
      intros E. assert (b = (p, Ap, np)) by (eapply nodup_blk_eq; [exact (ah_nodup H HH _ _ _ HP)| exact Hb| exact Hin| exact E]).
      subst b. cbn in K. apply NX. apply HX. exact K.
    - right; right; right; left. exists b. split; [| exact K].
      apply (ah_lb_remove_keep H HH); [exact (ah_nodup H HH _ _ _ HP)| exact Hb|].
      intros E. assert (b = (p, Ap, np)) by (eapply nodup_blk_eq; [exact (ah_nodup H HH _ _ _ HP)| exact Hb| exact Hin| exact E]).
      subst b. cbn in K. apply NX. apply HXS. exact K.
