                                       /\ (forall a, sh (blk_addr b) <= a < sh (blk_addr b) + nsh (blk_size b) -> rin_ivs X a))) ->
    xpres H LB SP X m m'.
  Proof.
    intros LB L' SP SP' X m m' AP HS COV a Ha [HC NX]. apply AP; [exact Ha|].
    unfold aclient_addr in *.
    destruct HC as [K|[K|[(b & Hb & K)|[(b & Hb & K)|K]]]]; [left; lia| right; left; exact K| | | right; right; right; right; exact K].
    - destruct (COV b Hb) as [IN|[CX _]]; [right; right; left; exists b; split; [exact IN| exact K]|].
      exfalso. apply NX. apply CX. unfold in_block in K. exact K.
    - destruct (COV b Hb) as [IN|[_ CXS]]; [right; right; right; left; exists b; split; [exact IN| exact K]|].
      exfalso. apply NX. apply CXS. exact K.
  Qed.

